function setupForm({ doc, call, router, updateField, createToast, $dialog, toast, deleteDoc }) {
  // small helper to render a combobox (input + UL list) using frappe-ui classes
  function comboboxHtml(id, placeholder) {
    return `
<div style="position:relative;">
  <input id="${id}_input" autocomplete="off" placeholder="${placeholder}" class="text-base rounded h-7 py-1.5 pl-2 pr-7 border border-[--surface-gray-2] bg-surface-gray-2 placeholder-ink-gray-4 w-full" />
  <input type="hidden" id="${id}_value" />
  <ul id="${id}_list" role="listbox" aria-labelledby="${id}_input" class="my-1 max-h-[12rem] overflow-y-auto p-1.5 pt-0" style="display:none;position:absolute;left:0;right:0;z-index:6000;background:var(--surface-modal,#fff);border-radius:6px;box-shadow:0 10px 25px rgba(0,0,0,0.08);margin-top:6px;">
    <!-- options injected here -->
  </ul>
</div>
`;
  }

  // attach behavior to a combobox: items = [{label, value}, ...]
  function attachCombobox(id, items, initialValue) {
    const input = document.getElementById(id + "_input");
    const list = document.getElementById(id + "_list");
    const hidden = document.getElementById(id + "_value");
    if (!input || !list || !hidden) return;
    let filtered = items.slice();
    let focusIndex = -1;

    function escapeHtml(s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    }

    function renderList() {
      list.innerHTML = filtered
        .map(
          (it, i) =>
            `<li class="flex cursor-pointer items-center rounded px-2.5 py-1.5 text-base" role="option" data-idx="${i}" data-value="${escapeHtml(
              it.value
            )}" tabindex="-1"><div class="flex-1 truncate text-ink-gray-7">${escapeHtml(it.label)}</div></li>`
        )
        .join("");
      list.style.display = filtered.length ? "block" : "none";
      focusIndex = -1;
    }

    function setSelection(it) {
      if (!it) return;
      input.value = it.label;
      hidden.value = it.value;
      list.style.display = "none";
      input.dispatchEvent(new Event("change", { bubbles: true }));
    }

    // initialize from initialValue (can be value or label)
    if (initialValue) {
      const found = items.find((it) => it.value === initialValue || it.label === initialValue);
      if (found) setSelection(found);
      else {
        input.value = initialValue;
        hidden.value = "";
      }
    }

    input.addEventListener("input", () => {
      const q = input.value.trim().toLowerCase();
      filtered = items.filter((it) => it.label.toLowerCase().includes(q));
      renderList();
    });

    input.addEventListener("focus", () => {
      filtered = items.slice();
      renderList();
    });

    input.addEventListener("keydown", (e) => {
      if (list.style.display === "none") return;
      const nodes = Array.from(list.querySelectorAll("li"));
      if (e.key === "ArrowDown") {
        e.preventDefault();
        focusIndex = Math.min(focusIndex + 1, nodes.length - 1);
        nodes[focusIndex]?.focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        focusIndex = Math.max(focusIndex - 1, 0);
        nodes[focusIndex]?.focus();
      } else if (e.key === "Enter") {
        e.preventDefault();
        if (focusIndex >= 0 && nodes[focusIndex]) {
          nodes[focusIndex].click();
        } else if (nodes[0]) {
          nodes[0].click();
        }
      } else if (e.key === "Escape") {
        list.style.display = "none";
      }
    });

    // delegate click
    list.addEventListener("click", (ev) => {
      const li = ev.target.closest("li");
      if (!li) return;
      const idx = parseInt(li.dataset.idx, 10);
      const it = filtered[idx];
      if (!it) return;
      setSelection(it);
      input.focus();
    });

    // click outside to close
    const onDocClick = (ev) => {
      if (!input || !list) return;
      if (!input.contains(ev.target) && !list.contains(ev.target)) {
        list.style.display = "none";
      }
    };
    document.addEventListener("click", onDocClick);

    // expose a small API to set value programmatically
    return {
      setValue(v) {
        const found = items.find((it) => it.value === v || it.label === v);
        if (found) setSelection(found);
        else {
          input.value = v;
          hidden.value = v;
        }
      },
      destroy() {
        document.removeEventListener("click", onDocClick);
      },
    };
  }

  return {
    actions: [
      {
        label: "Create Customer",
        onClick: () => {
          $dialog({
            title: "Create Customer",
            size: "2xl",
            html: `
<div class="p-4">
  <div class="grid" style="grid-template-columns:repeat(2,1fr);gap:12px;">
    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">Customer Name *</label>
      <input id="customer_name" class="text-base rounded h-7 py-1.5 pl-2 pr-2 border border-[--surface-gray-2] bg-surface-gray-2 w-full" />
    </div>

    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">Customer Type *</label>
      ${comboboxHtml("customer_type", "Select Type")}
    </div>

    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">Email</label>
      <input id="email_id" class="text-base rounded h-7 py-1.5 pl-2 pr-2 border border-[--surface-gray-2] bg-surface-gray-2 w-full" />
    </div>

    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">Phone</label>
      <input id="phone" class="text-base rounded h-7 py-1.5 pl-2 pr-2 border border-[--surface-gray-2] bg-surface-gray-2 w-full" />
    </div>

    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">Territory</label>
      <input id="territory" class="text-base rounded h-7 py-1.5 pl-2 pr-2 border border-[--surface-gray-2] bg-surface-gray-2 w-full" />
    </div>

    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">Billing Currency</label>
      <input id="default_currency" placeholder="INR" class="text-base rounded h-7 py-1.5 pl-2 pr-2 border border-[--surface-gray-2] bg-surface-gray-2 w-full" />
    </div>

    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">Annual Revenue</label>
      <input id="annual_revenue" type="number" step="0.01" class="text-base rounded h-7 py-1.5 pl-2 pr-2 border border-[--surface-gray-2] bg-surface-gray-2 w-full" />
    </div>

    <div>
      <label class="mb-2 text-sm text-ink-gray-5 block">No. of Employees</label>
      ${comboboxHtml("number_of_employees", "Select employees")}
    </div>

    <div style="grid-column:1 / -1">
      <label class="mb-2 text-sm text-ink-gray-5 block">Industry</label>
      ${comboboxHtml("industry", "Select industry")}
    </div>
  </div>
</div>
            `,
            actions: [
              {
                label: "Create",
                variant: "solid",
                onClick: async (close) => {
                  try {
                    const customer_name = (document.getElementById("customer_name") || {}).value?.trim();
                    const customer_type_value = (document.getElementById("customer_type_value") || {}).value || (document.getElementById("customer_type_input") || {}).value;
                    if (!customer_name || !customer_type_value) {
                      toast.error("Please fill required fields");
                      return;
                    }

                    const values = {
                      customer_name,
                      customer_type: customer_type_value,
                      email_id: (document.getElementById("email_id") || {}).value || null,
                      phone: (document.getElementById("phone") || {}).value || null,
                      territory: (document.getElementById("territory") || {}).value || null,
                      annual_revenue: parseFloat((document.getElementById("annual_revenue") || {}).value) || 0,
                      number_of_employees: (document.getElementById("number_of_employees_value") || {}).value || (document.getElementById("number_of_employees_input") || {}).value || null,
                      industry: (document.getElementById("industry_value") || {}).value || (document.getElementById("industry_input") || {}).value || null,
                      default_currency: (document.getElementById("default_currency") || {}).value || null,
                    };

                    const res = await call("frappe.client.insert", {
                      doc: {
                        doctype: "Customer",
                        customer_name: values.customer_name,
                        customer_type: values.customer_type,
                        email_id: values.email_id,
                        phone: values.phone,
                        territory: values.territory,
                        annual_revenue: values.annual_revenue,
                        number_of_employees: values.number_of_employees,
                        industry: values.industry,
                        default_currency: values.default_currency,
                      },
                    });

                    const created_name = res?.message?.name || res?.name || res?.data?.name || null;
                    toast.success("Customer Created Successfully");
                    // close dialog then navigate
                    if (typeof close === 'function') close.close();
                  } catch (e) {
                    console.error(e);
                    toast.error(e?.message || "Failed to Create Customer");
                  }
                },
              },
              { label: "Cancel", variant: "outline", onClick: (context) => {context?.close(); } },
            ],
          });

          // Prepare comboboxes and pre-fill from `doc`
          const customerTypeItems = [
            { label: "Company", value: "Company" },
            { label: "Individual", value: "Individual" },
            { label: "Partnership", value: "Partnership"},
          ];
          const employeesItems = [
            { label: "1-10", value: "1-10" },
            { label: "11-50", value: "11-50" },
            { label: "51-200", value: "51-200" },
            { label: "201-500", value: "201-500" },
            { label: "501-1000", value: "501-1000" },
            { label: "1000+", value: "1000+" },
          ];
          const industryItems = [
            { label: "Accounting", value: "Accounting" },
            { label: "Advertising", value: "Advertising" },
            { label: "Aerospace", value: "Aerospace" },
            { label: "Agriculture", value: "Agriculture" },
            { label: "Automotive", value: "Automotive" },
            { label: "Banking", value: "Banking" },
            { label: "Biotechnology", value: "Biotechnology" },
            { label: "Consulting", value: "Consulting" },
            { label: "Education", value: "Education" },
          ];

          // wire up after dialog DOM is ready
          setTimeout(() => {
            const ct = attachCombobox("customer_type", customerTypeItems, doc?.customer_type || doc?.custom_billing_type || "");
            const ne = attachCombobox("number_of_employees", employeesItems, doc?.number_of_employees || "");
            const ind = attachCombobox("industry", industryItems, doc?.industry || "");

            // prefill simple inputs from doc
            const prefill = {
              customer_name: doc?.organization_name || doc?.customer || doc?.party_name || "",
              email_id: doc?.email_id || doc?.contact_email || doc?.custom_org_email|| "",
              phone: doc?.phone || doc?.custom_phone || "",
              territory: doc?.territory || "",
              default_currency: doc?.default_currency || doc?.currency || "INR",
              annual_revenue: doc?.annual_revenue || doc?.estimated_revenue || "",
              // combobox hidden values if available
              customer_type: doc?.customer_type || doc?.custom_billing_type || "",
              number_of_employees: doc?.no_of_employees || "",
              industry: doc?.industry || "",
            };

            Object.keys(prefill).forEach((k) => {
              const el = document.getElementById(k);
              if (el) el.value = prefill[k];
            });

            // if combobox APIs returned, set their values
            if (ct && prefill.customer_type) ct.setValue(prefill.customer_type);
            if (ne && prefill.number_of_employees) ne.setValue(prefill.number_of_employees);
            if (ind && prefill.industry) ind.setValue(prefill.industry);
          }, 80);
        },
      },
    ],
  };
}

class CRMDeal {
  async onLoad() {
    // Adds "Open Project" action if one already exists for this deal.
    const existingProjects = await call('frappe.client.get_list', {
      doctype: 'Project',
      filters: { project_name: ['like', '%' + this.doc.name + '%'] },
      fields: ['name', 'project_name'],
      limit: 1,
    })

    if (existingProjects && existingProjects.length) {
      const project = existingProjects[0]
      this.actions = [
        ...(this.actions || []),
        {
          group: 'Actions',
          hideLabel: true,
          items: [
            {
              label: 'Open Project',
              icon: 'external-link',
              onClick: () => {
                window.open('/app/project/' + project.name, '_blank')
              },
            },
          ],
        },
      ]
    }
  }

  async status() {
    if (this.doc.status !== 'Won') return
    if (this.__msaProjectDialogShown) return
    this.__msaProjectDialogShown = true

    setTimeout(async () => {
      try {
        // Wait for frappe-crm to create + link the ERPNext Customer (server-side
        // hook fires on status=Won). If after polling it still hasn't appeared,
        // abort silently — no point showing the project dialog without a
        // customer to link it to.
        const fresh = await this.waitForErpnextCustomer()
        Object.assign(this.doc, fresh)

        if (!this.doc.erpnext_customer) {
          // No customer linked yet — surface a non-blocking toast (no dialog)
          // and reset the guard so the next save re-triggers the flow.
          this.__msaProjectDialogShown = false
          toast.info('Skipping project creation — no customer found')
          return
        }

        const proceed = await this.askCreateProject()
        if (!proceed) {
          this.__msaProjectDialogShown = false
          return
        }

        // 1. Project dialog uses the now-fresh customer link.
        const projectName = await this.showProjectDialog()

        // 2. MSA / Insurance on the same customer.
        await this.showMSAInsuranceDialog()

        if (projectName) {
          window.open('/app/project/' + projectName, '_blank')
        }
      } catch (e) {
        console.error(e)
        toast.error(
          e?.messages?.[0] || e?.message || 'Failed to process deal'
        )
      }
    }, 1200)
  }

  // ── Helper: poll for the server-created Customer link ───────────────────
  async waitForErpnextCustomer(maxAttempts = 6, delayMs = 1000) {
    let last = this.doc
    for (let i = 0; i < maxAttempts; i++) {
      last = await call('frappe.client.get', {
        doctype: 'CRM Deal',
        name: this.doc.name,
      })
      if (last.erpnext_customer) return last
      await new Promise((r) => setTimeout(r, delayMs))
    }
    // Even after polling we may still not have a customer (e.g. the auto-create
    // hook is disabled). Fall through with whatever the server returned last.
    return last
  }

  // ── Step 1: confirmation prompt ─────────────────────────────────────────
  async askCreateProject() {
    const values = await formDialog({
      title: __('Create Project?'),
      fields: [
        {
          fieldname: 'prompt_html',
          fieldtype: 'HTML',
          options: `<div style="font-size: 14px; line-height: 1.5; color: #333;">This deal is marked as <strong>Won</strong> 🎉<br/>Do you want to create a <strong>Project</strong> from this deal?<br/><br/><span style="color:#666; font-size:12px;">We'll create the project first using the auto-linked customer, then capture MSA &amp; Insurance details on that same customer.</span></div>`,
        },
      ],
      submitLabel: __('Yes, Create Project'),
    })
    return !!values
  }

  // ── Step 2: Project creation, pre-filled from the (refreshed) Deal ──────
  //
  // Returns the created project's name on success, or null on skip/cancel.
  async showProjectDialog() {
    try {
      const existingProjects = await call('frappe.client.get_list', {
        doctype: 'Project',
        filters: { project_name: ['like', '%' + this.doc.name + '%'] },
        fields: ['name'],
        limit: 1,
      })

      if (existingProjects && existingProjects.length) {
        toast.success('Project Already Exists')
        return existingProjects[0].name
      }

      const d = this.doc
      const dealDefaults = {
        customer: d.erpnext_customer || '',
        project_name: (d.organization_name || d.name) + ' - ' + d.name,
        custom_industry: d.industry || '',
        custom_territory: d.territory || '',
        custom_currency: d.currency || 'INR',
        estimated_costing: d.expected_deal_value || d.deal_value || 0,
        custom_total_hours_purchased: d.custom_estimatedpurchased_hours || 0,
        custom_project_manager: d.custom_project_manager || '',
        custom_client_point_of_contact: d.contact || '',
        custom_service_type: d.custom_service_type || '',
        project_type: d.custom_project_type || '',
        custom_project_size: d.custom__project_size || '',
        custom_complexity: d.custom_complexity_level || '',
        custom_duration: d.custom_duration || '',
        custom_billing_type: d.custom_billing_type || '',
        custom_timezone: d.custom_timezone || '',
        custom_previous_cms: d.custom_previous_cms || '',
        custom_host: d.custom_current_host || '',
        custom_deal_type: d.custom_deal_type || '',
        custom_restricted_under_nda: d.custom_restricted_under_nda || 0,
        notes: d.custom_description || '',
        company: d.company || '',
      }

      const values = await formDialog({
        title: __('Update Missing Fields'),
        size: '2xl',
        tabs: [
          {
            name: 'main',
            label: '',
            sections: [
              {
                name: 'row1',
                label: '',
                columns: [
                  {
                    name: 'col1',
                    fields: [
                      { label: 'Project Manager', fieldname: 'custom_project_manager', fieldtype: 'Link', options: 'User', reqd: 1 },
                      { label: 'Territory', fieldname: 'custom_territory', fieldtype: 'Link', options: 'Territory', reqd: 1 },
                      { label: 'Billing Type', fieldname: 'custom_billing_type', fieldtype: 'Select', options: 'Non-Billable\nFixed Cost\nRetainer\nTime and Material', reqd: 1 },
                    ],
                  },
                  {
                    name: 'col2',
                    fields: [
                      { label: 'Customer', fieldname: 'customer', fieldtype: 'Link', options: 'Customer', reqd: 1 },
                      { label: 'Currency', fieldname: 'custom_currency', fieldtype: 'Link', options: 'Currency', reqd: 1 },
                      { label: 'Total Hours Purchased', fieldname: 'custom_total_hours_purchased', fieldtype: 'Float', reqd: 1 },
                    ],
                  },
                  {
                    name: 'col3',
                    fields: [
                      { label: 'Service Type', fieldname: 'custom_service_type', fieldtype: 'Link', options: 'Service Type', reqd: 1 },
                      { label: 'Estimated Costing', fieldname: 'estimated_costing', fieldtype: 'Currency', reqd: 1 },
                      { label: 'Project Type', fieldname: 'project_type', fieldtype: 'Link', options: 'Project Type', reqd: 1 },
                    ],
                  },
                ],
              },
              {
                name: 'row2',
                label: '',
                columns: [
                  {
                    name: 'col1b',
                    fields: [
                      { label: 'Deal Type', fieldname: 'custom_deal_type', fieldtype: 'Select', options: '\nOld-Old\nOld-New\nNew-New', reqd: 1 },
                      { label: 'Project Name', fieldname: 'project_name', fieldtype: 'Data', reqd: 1 },
                      { label: 'Project Size', fieldname: 'custom_project_size', fieldtype: 'Select', options: '\nSmall (< $50K)\nMedium ($50K - $100K)\nLarge ($100K+)', reqd: 1 },
                    ],
                  },
                  {
                    name: 'col2b',
                    fields: [
                      { label: 'Complexity', fieldname: 'custom_complexity', fieldtype: 'Select', options: '\nC1\nC2\nC3', reqd: 1 },
                      { label: 'Timezone', fieldname: 'custom_timezone', fieldtype: 'Data', placeholder: 'Enter Timezone', reqd: 1 },
                      { label: 'Duration', fieldname: 'custom_duration', fieldtype: 'Select', options: '\nShort-term (< 3 months)\nMedium-term (3-12 months)\nLong-term (> 1 year)', reqd: 1 },
                    ],
                  },
                  {
                    name: 'col3b',
                    fields: [
                      { label: 'Industry', fieldname: 'custom_industry', fieldtype: 'Link', options: 'Industry Type', reqd: 1 },
                      { label: 'Previous CMS', fieldname: 'custom_previous_cms', fieldtype: 'Data', placeholder: 'Enter Previous CMS', reqd: 1 },
                      { label: 'Host', fieldname: 'custom_host', fieldtype: 'Link', options: 'Host', reqd: 1 },
                    ],
                  },
                ],
              },
              {
                name: 'row3',
                label: '',
                columns: [
                  {
                    name: 'col1c',
                    fields: [
                      { label: 'Company', fieldname: 'company', fieldtype: 'Link', options: 'Company', reqd: 1 },
                      { label: 'Restricted under NDA', fieldname: 'custom_restricted_under_nda', fieldtype: 'Check' },
                    ],
                  },
                  {
                    name: 'col2c',
                    fields: [
                      { label: 'Contact Person', fieldname: 'custom_client_point_of_contact', fieldtype: 'Link', options: 'Contact' },
                    ],
                  },
                  {
                    name: 'col3c',
                    fields: [
                      { label: 'Description', fieldname: 'notes', fieldtype: 'Text', reqd: 1 },
                    ],
                  },
                ],
              },
            ],
          },
        ],
        defaults: dealDefaults,
        submitLabel: __('Create Project'),
      })

      if (!values) return null

      const uniqueProjectName = values.project_name.includes(this.doc.name)
        ? values.project_name
        : values.project_name + ' - ' + this.doc.name

      const project = await call('frappe.client.insert', {
        doc: {
          doctype: 'Project',
          project_name: uniqueProjectName,
          customer: values.customer,
          company: values.company,
          custom_project_manager: values.custom_project_manager,
          estimated_costing: values.estimated_costing,
          custom_total_hours_purchased: values.custom_total_hours_purchased,
          notes: values.notes,
          custom_territory: values.custom_territory,
          custom_currency: values.custom_currency,
          custom_industry: values.custom_industry,
          custom_service_type: values.custom_service_type,
          custom_deal_type: values.custom_deal_type,
          custom_complexity: values.custom_complexity,
          custom_timezone: values.custom_timezone,
          custom_previous_cms: values.custom_previous_cms,
          custom_billing_type: values.custom_billing_type,
          project_type: values.project_type,
          custom_project_size: values.custom_project_size,
          custom_duration: values.custom_duration,
          custom_host: values.custom_host,
          custom_restricted_under_nda: values.custom_restricted_under_nda || 0,
          custom_client_point_of_contact: values.custom_client_point_of_contact || null,
          status: 'Open',
        },
      })

      toast.success('Project Created Successfully')
      return project?.name || project?.message?.name || null
    } catch (e) {
      console.error(e)
      toast.error(
        e?.messages?.[0] || e?.message || 'Failed to create project'
      )
      return null
    }
  }

  // ── Step 3: MSA & Insurance on the Customer ─────────────────────────────
  async showMSAInsuranceDialog() {
    try {
      if (!this.doc.erpnext_customer) {
        toast.error('Skipping MSA and Insurance — no ERPNext customer linked')
        return
      }

      const customer = await call('frappe.client.get', {
        doctype: 'Customer',
        name: this.doc.erpnext_customer,
      })

      const values = await formDialog({
        title: __('MSA & Insurance Details'),
        size: '2xl',
        tabs: [
          {
            name: 'main',
            label: '',
            sections: [
              {
                name: 'msa_insurance',
                label: '',
                columns: [
                  {
                    name: 'left',
                    fields: [
                      { label: 'MSA Start Date', fieldname: 'custom_msa_start_date', fieldtype: 'Date' },
                      { label: 'MSA End Date', fieldname: 'custom_msa_end_date', fieldtype: 'Date' },
                      { label: 'MSA Document Link', fieldname: 'custom_msa_document_link', fieldtype: 'Data', placeholder: 'Enter document link or path' },
                    ],
                  },
                  {
                    name: 'right',
                    fields: [
                      { label: 'Insurance Requested', fieldname: 'custom_insurance_requested', fieldtype: 'Check' },
                      { label: 'Insurance Start Date', fieldname: 'custom_insurance_start_date', fieldtype: 'Date', depends_on: 'eval:doc.custom_insurance_requested' },
                      { label: 'Insurance End Date', fieldname: 'custom_insurance_end_date', fieldtype: 'Date', depends_on: 'eval:doc.custom_insurance_requested' },
                      { label: 'Insurance Document Link', fieldname: 'custom_insurance_document_link', fieldtype: 'Data', placeholder: 'Enter document link or path', depends_on: 'eval:doc.custom_insurance_requested' },
                    ],
                  },
                ],
              },
            ],
          },
        ],
        defaults: {
          custom_msa_start_date: customer.custom_msa_start_date || null,
          custom_msa_end_date: customer.custom_msa_end_date || null,
          custom_msa_document_link: customer.custom_msa_document_link || null,
