        const idx = toggle.getAttribute('data-idx')
        const full = document.querySelector(`.address-full-${idx}`)
        const icon = document.querySelector(`.address-icon[data-idx="${idx}"]`)

        if (full.style.display === 'none') {
          full.style.display = 'block'
          icon.style.transform = 'rotate(180deg)'
        } else {
          full.style.display = 'none'
          icon.style.transform = 'rotate(0deg)'
        }
      })
    })

    document.querySelectorAll('.add-address-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault()
        me.showAddressDialog(doc.name)
      })
    })

    document.querySelectorAll('.edit-address-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault()
        const addressName = btn.getAttribute('data-address')
        me.showEditAddressDialog(addressName)
      })
      btn.addEventListener('mouseenter', (e) => { e.currentTarget.style.background = '#f0f0f0'; e.currentTarget.style.color = '#000' })
      btn.addEventListener('mouseleave', (e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = '#666' })
    })

    document.querySelectorAll('.unlink-address-link').forEach(link => {
      link.addEventListener('click', (e) => {
        e.preventDefault()
        const addressName = link.getAttribute('data-address')
        me.unlinkAddress(addressName, doc.name)
      })
      link.addEventListener('mouseenter', (e) => { e.currentTarget.style.background = '#fdecec'; e.currentTarget.style.color = '#c0392b' })
      link.addEventListener('mouseleave', (e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = '#666' })
    })
  }

  addressFormFields(forCreate) {
    const createDep = (extra) => forCreate ? `eval:doc.mode == 'create'${extra || ''}` : (extra ? `eval:${extra.replace(/^.*?&&\s*/, '')}` : null)
    const reqdProp = forCreate ? { mandatory_depends_on: `eval:doc.mode == 'create'` } : { reqd: 1 }
    return [
      { fieldname: 'address_title', fieldtype: 'Data', label: __('Address Title'), ...reqdProp, ...(forCreate ? { depends_on: createDep() } : {}) },
      { fieldname: 'address_type', fieldtype: 'Select', label: __('Address Type'), options: 'Billing\nShipping\nOffice\nPersonal\nPlant\nPostal\nShop\nSubsidiary\nWarehouse\nCurrent\nPermanent\nOther', ...(forCreate ? { depends_on: createDep() } : {}) },
      { fieldname: 'address_line1', fieldtype: 'Data', label: __('Address Line 1'), ...reqdProp, ...(forCreate ? { depends_on: createDep() } : {}) },
      { fieldname: 'address_line2', fieldtype: 'Data', label: __('Address Line 2'), ...(forCreate ? { depends_on: createDep() } : {}) },
      { fieldname: 'city', fieldtype: 'Data', label: __('City'), ...reqdProp, ...(forCreate ? { depends_on: createDep() } : {}) },
      { fieldname: 'country', fieldtype: 'Link', label: __('Country'), options: 'Country', ...reqdProp, ...(forCreate ? { depends_on: createDep() } : {}) },
      {
        fieldname: 'state',
        fieldtype: 'Data',
        label: __('State / Province'),
        depends_on: forCreate ? `eval:doc.mode == 'create' && doc.country !== 'India'` : `eval:doc.country !== 'India'`,
      },
      {
        fieldname: 'state_india',
        fieldtype: 'Select',
        label: __('State'),
        options: 'Andaman and Nicobar Islands\nAndhra Pradesh\nArunachal Pradesh\nAssam\nBihar\nChandigarh\nChhattisgarh\nDadra and Nagar Haveli and Daman and Diu\nDelhi\nGoa\nGujarat\nHaryana\nHimachal Pradesh\nJammu and Kashmir\nJharkhand\nKarnataka\nKerala\nLadakh\nLakshadweep Islands\nMadhya Pradesh\nMaharashtra\nManipur\nMeghalaya\nMizoram\nNagaland\nOdisha\nPuducherry\nPunjab\nRajasthan\nSikkim\nTamil Nadu\nTelangana\nTripura\nUttar Pradesh\nUttarakhand\nWest Bengal',
        depends_on: forCreate ? `eval:doc.mode == 'create' && doc.country === 'India'` : `eval:doc.country === 'India'`,
      },
      { fieldname: 'pincode', fieldtype: 'Data', label: __('Postal Code'), ...(forCreate ? { depends_on: createDep() } : {}) },
      { fieldname: 'is_primary_address', fieldtype: 'Check', label: __('Preferred Billing Address'), ...(forCreate ? { depends_on: createDep() } : {}) },
      { fieldname: 'is_shipping_address', fieldtype: 'Check', label: __('Preferred Shipping Address'), ...(forCreate ? { depends_on: createDep() } : {}) },
    ]
  }

  async showAddressDialog(leadName) {
    const me = this
    try {
      const values = await formDialog({
        title: __('Add Address'),
        fields: [
          { fieldname: 'mode', fieldtype: 'Select', label: __('Address Mode'), options: [{ label: 'Create New', value: 'create' }, { label: 'Link Existing', value: 'link' }], reqd: 1, default: 'create' },
          { fieldname: 'existing_address', fieldtype: 'Link', label: __('Select Address'), options: 'Address', depends_on: "eval:doc.mode == 'link'", mandatory_depends_on: "eval:doc.mode == 'link'" },
          ...me.addressFormFields(true),
        ],
        submitLabel: __('Save'),
      })

      if (!values) return

      if (values.mode === 'link') {
        await me.linkExistingAddress(values.existing_address, leadName)
      } else {
        const state = values.country === 'India' ? values.state_india : values.state
        await me.saveNewAddress({ ...values, state }, leadName)
      }
    } catch (e) {
      console.error('Dialog error:', e)
      toast.error(e?.message || __('Failed to open dialog'))
    }
  }

  async showEditAddressDialog(addressName) {
    const me = this
    try {
      const address = await call('frappe.client.get', { doctype: 'Address', name: addressName })
      const isIndia = address.country === 'India'

      const values = await formDialog({
        title: __('Edit Address'),
        size: 'xl',
        fields: me.addressFormFields(false),
        defaults: {
          address_title: address.address_title || '',
          address_type: address.address_type || '',
          address_line1: address.address_line1 || '',
          address_line2: address.address_line2 || '',
          city: address.city || '',
          country: address.country || '',
          state: isIndia ? '' : (address.state || ''),
          state_india: isIndia ? (address.state || '') : '',
          pincode: address.pincode || '',
          is_primary_address: address.is_primary_address || 0,
          is_shipping_address: address.is_shipping_address || 0,
        },
        submitLabel: __('Update'),
      })

      if (!values) return

      const state = values.country === 'India' ? values.state_india : values.state

      await call('frappe.client.set_value', {
        doctype: 'Address',
        name: addressName,
        fieldname: {
          address_title: values.address_title,
          address_type: values.address_type || null,
          address_line1: values.address_line1,
          address_line2: values.address_line2 || null,
          city: values.city,
          state: state || null,
          pincode: values.pincode || null,
          country: values.country,
          is_primary_address: values.is_primary_address || 0,
          is_shipping_address: values.is_shipping_address || 0,
        },
      })

      toast.success(__('Address updated'))
      await me.renderAddresses()
    } catch (e) {
      console.error('showEditAddressDialog error:', e)
      toast.error(e?.messages?.[0] || e?.message || __('Failed to update address'))
    }
  }

  async linkExistingAddress(addressName, leadName) {
    try {
      const address = await call('frappe.client.get', { doctype: 'Address', name: addressName })

      const alreadyLinked = address.links && address.links.some(
        link => link.link_doctype === 'CRM Lead' && link.link_name === leadName
      )

      if (alreadyLinked) {
        toast.error(__('This address is already linked to this deal'))
        return
      }

      if (!address.links) address.links = []
      address.links.push({ doctype: 'Dynamic Link', link_doctype: 'CRM Lead', link_name: leadName })

      await call('frappe.client.set_value', { doctype: 'Address', name: addressName, fieldname: 'links', value: address.links })
      toast.success(__('Address linked successfully'))
      await this.renderAddresses()
    } catch (e) {
      console.error('linkExistingAddress error:', e)
      toast.error(e?.messages?.[0] || e?.message || __('Failed to link address'))
    }
  }

  async saveNewAddress(values, leadName) {
    try {
      if (!values.address_title || !values.address_line1 || !values.city || !values.country) {
        toast.error(__('Please fill Address Title, Line 1, City and Country'))
        return
      }

      await call('frappe.client.insert', {
        doc: {
          doctype: 'Address',
          address_title: values.address_title,
          address_type: values.address_type || null,
          address_line1: values.address_line1,
          address_line2: values.address_line2 || null,
          city: values.city,
          state: values.state || null,
          pincode: values.pincode || null,
          country: values.country,
          is_primary_address: values.is_primary_address || 0,
          is_shipping_address: values.is_shipping_address || 0,
          links: [{ doctype: 'Dynamic Link', link_doctype: 'CRM Lead', link_name: leadName }],
        },
      })

      toast.success(__('Address created and linked'))
      await this.renderAddresses()
    } catch (e) {
      console.error('saveNewAddress error:', e)
      toast.error(e?.messages?.[0] || e?.message || __('Failed to create address'))
    }
  }

  async unlinkAddress(addressName, leadName) {
    const me = this
    try {
      const address = await call('frappe.client.get', { doctype: 'Address', name: addressName })
      address.links = (address.links || []).filter(
        link => !(link.link_doctype === 'CRM Lead' && link.link_name === leadName)
      )

      await call('frappe.client.set_value', { doctype: 'Address', name: addressName, fieldname: 'links', value: address.links })
      toast.success(__('Address unlinked'))
      await me.renderAddresses()
    } catch (e) {
      console.error('unlinkAddress error:', e)
      toast.error(e?.messages?.[0] || e?.message || __('Failed to unlink address'))
    }
  }
}

